function extraTexture(k,id){if(ATELIER_FINISHES[k])return atelierTexture(k,id);const m=EXTRA_FINISHES[k];let detail='';if(m.texture==='stone')detail='<path d="M0 0H64V42H0ZM32 0v42"/><path d="M5 12l15 2m22 20 14-3" opacity=".4"/>';if(m.texture==='cobble')detail='<path d="M1 2l18-1 3 16-20 2Zm24-1h21l-2 20-18-2ZM2 23l22-1 2 17-25 2Zm28 0 17 2-1 14H30Z"/><path d="M50 1h14v18H51Zm0 23h14v18H50Z"/>';if(m.texture==='mosaic')detail='<path d="M0 0H64V42H0ZM16 0v42m16-42v42m16-42v42M0 14h64M0 28h64"/><rect x="17" y="15" width="14" height="12" fill="#debd8d"/><rect x="49" y="1" width="14" height="12" fill="#8f5c43"/>';if(m.texture==='tile')detail='<path d="M0 0H64V42H0ZM32 0v42M0 21h64"/><path d="M16 3l12 8-12 8-12-8Zm32 21 12 8-12 8-12-8Z" fill="#7f8b6d"/>';if(m.texture==='brick')detail='<path d="M0 0H64V42H0ZM0 21h64M32 0v21M16 21v21m32-21v21"/><path d="M3 5l13 2m25 23 17 1" opacity=".5"/>';if(m.texture==='mulch')detail='<path d="M5 3l13 5m10 10 17-3m-39 16 12-6m27 5 12 6m-5-30 10 6" stroke-width="3"/>';if(m.texture==='fine')detail=Array.from({length:18},(_,i)=>`<circle cx="${(i*17)%64}" cy="${(i*13)%42}" r="1"/>`).join('');return `<pattern id="${id}" width="64" height="42" patternUnits="userSpaceOnUse"><rect width="64" height="42" fill="${m.base}"/><g stroke="${m.line}" stroke-width="1.2" fill="none">${detail}</g></pattern>`}
const VIEW_PRESETS={composite:{name:'All layers',ground:true,above:true,underground:true},ground:{name:'Ground',ground:true,above:false,underground:false},above:{name:'Above ground',ground:false,above:true,underground:false},underground:{name:'Underground',ground:false,above:false,underground:true}};
const STRING_TYPES={festoon:{name:'Festoon globe strand',rate:6,spacing:2,color:'#f5d796'},fairy:{name:'Fairy-light strand',rate:3,spacing:.75,color:'#f7e6be'},led:{name:'Linear LED concept',rate:8,spacing:1,color:'#eedbb4'}};
let drawingString='festoon',stringHeight=8,stringSpacing=2,stringSag=.12,viewZoom=100;
function upgradeLayers(){S.view??='composite';S.layers??={ground:true,above:true,underground:true};if(S.labelDisplayVersion!==1){S.labels=false;S.labelDisplayVersion=1}S.labels??=false;S.references??=true;S.strings??=[]}
function validLayerData(v){const pts=p=>p&&Number.isFinite(p.x)&&Number.isFinite(p.y)&&p.x>=0&&p.x<=1&&p.y>=0&&p.y<=1;return (!v.strings||(Array.isArray(v.strings)&&v.strings.length<=30&&v.strings.every(s=>typeof s.id==='string'&&STRING_TYPES[s.kind]&&Number.isFinite(s.spacing)&&s.spacing>=.5&&s.spacing<=10&&Number.isFinite(s.height)&&s.height>=1&&s.height<=25&&Number.isFinite(s.sag)&&s.sag>=0&&s.sag<=.3&&Array.isArray(s.points)&&s.points.length>=2&&s.points.length<=50&&s.points.every(pts))))&&(!v.layers||['ground','above','underground'].every(k=>typeof v.layers[k]==='boolean'))&&(!v.view||VIEW_PRESETS[v.view]||v.view==='custom')}
function setLayerView(name,{navigate=false}={}){const p=VIEW_PRESETS[name];if(!p)return;S.view=name;S.layers={ground:p.ground,above:p.above,underground:p.underground};selection=null;draft=[];tool='select';photoMode=false;viewZoom=100;if(navigate){catalogSearch='';catalogGroup='all';S.step=name==='underground'?3:name==='ground'?4:name==='above'?6:S.step}renderAll(true);scheduleSave()}
function ensureLayer(k){if(!S.layers[k]){S.layers[k]=true;S.view='custom'}}
function layerBarMarkup(){return `<div class="layer-header"><div><span class="eyebrow">Design layers</span><p>Ground surfaces · above-ground objects · underground services</p></div><div class="layer-presets" role="group" aria-label="Design layer views">${Object.entries(VIEW_PRESETS).map(([k,p])=>`<button data-view="${k}" class="${S.view===k?'active':''}" aria-pressed="${S.view===k}">${p.name}${k==='underground'?` <b>${S.routes.length}</b>`:''}</button>`).join('')}</div></div><details class="layer-options"><summary>Visibility & zoom</summary><div class="layer-settings"><label><input type="checkbox" data-visible-layer="ground" ${S.layers.ground?'checked':''}> Ground</label><label><input type="checkbox" data-visible-layer="above" ${S.layers.above?'checked':''}> Above ground</label><label><input type="checkbox" data-visible-layer="underground" ${S.layers.underground?'checked':''}> Underground</label><label><input type="checkbox" id="show-labels" ${S.labels?'checked':''}> Show all object labels</label><label><input type="checkbox" id="show-references" ${S.references?'checked':''}> Footprint references</label><label class="zoom-label">Zoom <input id="canvas-zoom" type="range" min="75" max="200" step="25" value="${viewZoom}"><span>${viewZoom}%</span></label></div><div class="layer-shortcuts"><button id="open-utilities" class="text-btn">Design underground services</button><button id="open-strings" class="text-btn">Draw string lights</button><span>${S.view==='underground'?'Ground and objects are hidden. Routes stay visible above reference outlines.':S.view==='above'?'Surface textures are muted so objects and labels stand out.':'Visibility controls change the drawing only; they never remove design items or costs.'}</span></div></details>${layerQuickActions()}`}
function layerQuickActions(){if(S.layers.underground&&!S.layers.ground&&!S.layers.above)return `<div class="layer-quick-actions"><label>Underground service type<select id="layer-service">${Object.entries(UTILITY_TYPES).map(([k,u])=>`<option value="${k}" ${routeKind===k?'selected':''}>${u.name}</option>`).join('')}</select></label><button id="layer-add-route" class="btn small">+ Add planned service sketch</button><span>Editable diagram only. Set the actual route in the details panel.</span></div>`;if(S.layers.above&&!S.layers.ground&&!S.layers.underground)return `<div class="layer-quick-actions"><label>Overhead light style<select id="layer-strand">${Object.entries(STRING_TYPES).map(([k,s])=>`<option value="${k}" ${drawingString===k?'selected':''}>${s.name}</option>`).join('')}</select></label><button id="layer-add-string" class="btn small">+ Add editable light strand</button><span>Move the anchor points, then switch to Night to preview.</span></div>`;return ''}
function renderLayerBar(){const el=$('#layer-bar');if(!el)return;el.innerHTML=layerBarMarkup();if($('#layer-service')){$('#layer-service').onchange=e=>routeKind=e.target.value;$('#layer-add-route').onclick=()=>{routeState='planned';routeReference='';quickUtility()}}if($('#layer-strand')){$('#layer-strand').onchange=e=>{drawingString=e.target.value;stringSpacing=STRING_TYPES[drawingString].spacing};$('#layer-add-string').onclick=()=>newString([{x:.15,y:Math.min(.75,.18+S.strings.length*.12)},{x:.85,y:Math.min(.75,.18+S.strings.length*.12)}])}$$('[data-view]').forEach(b=>b.onclick=()=>setLayerView(b.dataset.view));$$('[data-visible-layer]').forEach(inp=>inp.onchange=()=>{S.layers[inp.dataset.visibleLayer]=inp.checked;S.view='custom';selection=null;renderAll();scheduleSave()});$('#show-labels').onchange=e=>{S.labels=e.target.checked;renderAll();scheduleSave()};$('#show-references').onchange=e=>{S.references=e.target.checked;renderAll();scheduleSave()};$('#canvas-zoom').oninput=e=>{viewZoom=+e.target.value;renderCanvas();$('#canvas-zoom').nextElementSibling.textContent=viewZoom+'%'};$('#open-utilities').onclick=()=>{setLayerView('underground',{navigate:true});notify('Choose a service and draw a route, or add an editable sketch from the service panel.')};$('#open-strings').onclick=()=>{setLayerView('above');S.step=7;renderAll(true);$('#string-tools')?.setAttribute('open','');notify('Choose a string-light style and draw its anchor points, or add an editable strand.')}}
function technicalRouteMarkup(r,b=bounds(),{project=null,offset=0}={}){if(routeVisibility[r.kind]===false)return'';const scale=drawingLabelScale(!!project),u=UTILITY_TYPES[r.kind]||UTILITY_TYPES.unknown,selected=selection?.type==='route'&&selection.id===r.id,points=r.points.map(p=>{const q=project?project(p):xy(p,b);return{x:q.x,y:q.y+offset}}),p0=points[0],mid=points[Math.floor((points.length-1)/2)],label=(r.name||u.name)+' · '+pathLength(r).toFixed(1)+' ft',count=(label.length*5.6+18)*scale,dash=r.status==='verified'?'':r.status==='unverified'?'3 7':'13 6';let h=`<g data-route-id="${esc(r.id)}" class="service-route"><title>${esc(label)} · ${esc(ROUTE_STATES[r.status])}</title><polyline points="${points.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="#faf5e7" stroke-width="${(selected?11:9)*scale}" stroke-linejoin="round" opacity=".9"/><polyline points="${points.map(p=>p.x+','+p.y).join(' ')}" fill="none" stroke="${u.color}" stroke-width="${(selected?6:4.5)*scale}" stroke-dasharray="${dash}" stroke-linejoin="round"/>`;if(!project)points.forEach((p,i)=>h+=`<g data-route-vertex="${i}" class="svg-handle"><circle cx="${p.x}" cy="${p.y}" r="${(selected?8:5)*scale}" fill="${selected?'#f8e7bf':'#f6f1e3'}" stroke="${u.color}" stroke-width="2"/><text x="${p.x+10}" y="${p.y+14}" font-size="8" font-family="Arial" fill="#425843">${selected?i+1:''}</text></g>`);if(S.labels||S.view==='underground'||selected)h+=`<g pointer-events="none"><rect x="${mid.x+7}" y="${mid.y-29*scale}" width="${count}" height="${20*scale}" rx="3" fill="#faf5e7" stroke="${u.color}"/><text x="${mid.x+7+8*scale}" y="${mid.y-15*scale}" font-family="Arial" font-size="${10*scale}" fill="#2d4938">${esc(label)}</text></g>`;return h+'</g>'}
function itemLabel(i,b=bounds()){const scale=drawingLabelScale(false),p=xy(i,b),name=CATALOG[i.kind].name.replace(/ concept$/,''),short=scale>1.8?name.slice(0,21)+(name.length>21?'…':''):name,text=scale>1.8?short:name+' · '+i.w+'×'+i.h+' ft',w=Math.min(290,text.length*6.5+16)*scale,y=p.y+Math.max(8,i.h*b.scale*.4);return `<g pointer-events="none" class="object-plan-label"><path d="M${p.x} ${y}v${14*scale}" stroke="#456342" stroke-width="1"/><rect x="${p.x-w/2}" y="${y+11*scale}" width="${w}" height="${22*scale}" rx="3" fill="#fbf6e8" fill-opacity=".95" stroke="#b7bea8"/><text x="${p.x}" y="${y+26*scale}" text-anchor="middle" font-family="Arial" font-size="${12*scale}" fill="#2e4b35">${esc(text)}</text></g>`}
function referenceFootprints(b){if(!S.references)return'';return S.items.filter(i=>CATALOG[i.kind].occupies).map(i=>`<g pointer-events="none"><polygon points="${footprintPoints(i).map(p=>{const q=xy(p,b);return q.x+','+q.y}).join(' ')}" fill="none" stroke="#8c9b8b" stroke-dasharray="5 5" stroke-width="1.5"/><text x="${xy(i,b).x}" y="${xy(i,b).y}" text-anchor="middle" font-family="Arial" font-size="11" fill="#809181">${esc(CATALOG[i.kind].name)} footprint</text></g>`).join('')}
function stringSamples(s,project=null){const bulbs=[];for(let j=0;j<s.points.length-1;j++){const a=s.points[j],b=s.points[j+1],len=Math.hypot((b.x-a.x)*S.width,(b.y-a.y)*S.depth),count=Math.max(1,Math.ceil(len/s.spacing));for(let n=j?1:0;n<=count;n++){const t=n/count,p={x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t},q=project?project(p):xy(p);if(project)q.y+=Math.sin(Math.PI*t)*s.sag*len*bounds().scale*.5-s.height*bounds().scale*.45;bulbs.push({...q,t,j})}}return bulbs.slice(0,400)}
function stringMarkup(s,{project=null}={}){const spec=STRING_TYPES[s.kind],selected=selection?.type==='string'&&selection.id===s.id,heightOffset=project?s.height*bounds().scale*.45:0,anchors=s.points.map(p=>{const q=project?project(p):xy(p);return{x:q.x,y:q.y-heightOffset}});let d='M'+anchors[0].x+','+anchors[0].y;for(let i=1;i<anchors.length;i++){const a=anchors[i-1],b=anchors[i],len=Math.hypot((s.points[i].x-s.points[i-1].x)*S.width,(s.points[i].y-s.points[i-1].y)*S.depth);d+=project?` Q${(a.x+b.x)/2},${(a.y+b.y)/2+s.sag*len*bounds().scale} ${b.x},${b.y}`:` L${b.x},${b.y}`}let h=`<g data-string-id="${esc(s.id)}"><title>${esc(spec.name)} · ${pathLength(s).toFixed(1)} ft planned span</title><path d="${d}" fill="none" stroke="#f3e9d1" stroke-width="6"/><path d="${d}" fill="none" stroke="${selected?'#a63e2e':'#4e5949'}" stroke-width="${s.kind==='led'?3:1.8}"/>`;for(const p of stringSamples(s,project)){if(S.night&&S.lights)h+=`<circle cx="${p.x}" cy="${p.y+4}" r="${s.kind==='fairy'?12:20}" fill="url(#halo)"/>`;h+=`<path d="M${p.x} ${p.y}v4" stroke="#4c5847"/><circle cx="${p.x}" cy="${p.y+5}" r="${s.kind==='fairy'?2.2:4}" fill="${S.lights?spec.color:'#a9b19e'}" stroke="#887b53" stroke-width=".8"/>`}anchors.forEach((p,i)=>{h+=`<g ${project?'':`data-string-vertex="${i}" class="svg-handle"`}><circle cx="${p.x}" cy="${p.y}" r="${selected?7:4}" fill="#f5f0df" stroke="#986447" stroke-width="2"/></g>`;if(project)h+=`<path d="M${p.x} ${p.y}v${heightOffset}" stroke="#697961" stroke-dasharray="3 4" opacity=".5"/>`});if(S.labels||selected){const p=anchors[0];h+=`<text x="${p.x+9}" y="${p.y-11}" font-family="Arial" font-size="10" fill="${S.night?'#f6e3b2':'#344d38'}" paint-order="stroke" stroke="${S.night?'#263b35':'#f6f0e2'}" stroke-width="3">${esc(spec.name)} · ${pathLength(s).toFixed(1)} ft</text>`}return h+'</g>'}
function stringTools(){return `<details id="string-tools" class="string-tools" ${tool==='string'||S.view==='above'?'open':''}><summary>String lights & overhead strands (${S.strings.length})</summary><p class="note">Draw anchor points or add an editable sketch. Height and sag are illustrative, not structural or electrical specifications.</p><label class="field">Strand style<select id="string-kind">${Object.entries(STRING_TYPES).map(([k,s])=>`<option value="${k}" ${drawingString===k?'selected':''}>${s.name}</option>`).join('')}</select></label><div class="field-row"><label class="field">Visual height · ft<input id="string-height" type="number" min="1" max="25" step=".5" value="${stringHeight}"></label><label class="field">Bulb spacing · ft<input id="string-spacing" type="number" min=".5" max="10" step=".25" value="${stringSpacing}"></label></div><button class="outline-btn" id="draw-string">+ Draw a light strand</button><button class="text-btn" id="quick-string">+ Add an editable strand</button>${tool==='string'&&draft.length?'<button class="outline-btn" id="finish-draw">Finish light strand ✓</button><button class="text-btn" id="cancel-draw">Cancel drawing</button>':''}${S.strings.map(s=>`<button class="text-btn" data-string-select="${esc(s.id)}">${esc(s.name)} · ${pathLength(s).toFixed(1)} ft</button>`).join('')}</details>`}
function newString(points){if(S.strings.length>=30){notify('This project supports up to 30 strands.');return}change(()=>{ensureLayer('above');const s={id:uid(),name:STRING_TYPES[drawingString].name,kind:drawingString,height:stringHeight,spacing:stringSpacing,sag:stringSag,points:clone(points)};S.strings.push(s);selection={type:'string',id:s.id};tool='select';draft=[]},{controls:true})}
function bindStringTools(){if(!$('#draw-string'))return;$('#string-kind').onchange=e=>{drawingString=e.target.value;stringSpacing=STRING_TYPES[drawingString].spacing;$('#string-spacing').value=stringSpacing};$('#string-height').onchange=e=>stringHeight=clamp(+e.target.value||8,1,25);$('#string-spacing').onchange=e=>stringSpacing=clamp(+e.target.value||2,.5,10);$('#draw-string').onclick=()=>{ensureLayer('above');tool='string';draft=[];selection=null;renderAll(true);notify('Tap at least two anchor points, then finish the light strand.')};$('#quick-string').onclick=()=>newString([{x:.15,y:Math.min(.75,.18+S.strings.length*.12)},{x:.85,y:Math.min(.75,.18+S.strings.length*.12)}]);$$('[data-string-select]').forEach(b=>b.onclick=()=>{selection={type:'string',id:b.dataset.stringSelect};ensureLayer('above');renderAll()})}
function stringInspector(s){return `<h3>${esc(s.name)}</h3><span class="object-badge">${pathLength(s).toFixed(1)} ft planned span</span><label class="field">Light style<select id="edit-string-kind">${Object.entries(STRING_TYPES).map(([k,spec])=>`<option value="${k}" ${s.kind===k?'selected':''}>${spec.name}</option>`).join('')}</select></label><div class="field-row"><label class="field">Visual height · ft<input id="edit-string-height" type="number" min="1" max="25" step=".5" value="${s.height}"></label><label class="field">Bulb spacing · ft<input id="edit-string-spacing" type="number" min=".5" max="10" step=".25" value="${s.spacing}"></label></div><label class="field">Visual sag<input id="edit-string-sag" type="range" min="0" max=".3" step=".02" value="${s.sag}" style="width:100%"></label><p class="note">Above-ground lighting. Select Night and turn lights on to preview the bulbs. Anchors, weather ratings, circuits and safe span lengths need product-specific review.</p>${pointFields(s.points,'sv')}<button class="text-btn delete-photo" id="delete-string">Remove light strand</button>`}
function bindStringInspector(s){$('#edit-string-kind').onchange=e=>change(()=>{s.kind=e.target.value;s.name=STRING_TYPES[s.kind].name});for(const [k,min,max]of [['height',1,25],['spacing',.5,10],['sag',0,.3]])$('#edit-string-'+k).onchange=e=>{const v=+e.target.value;if(Number.isFinite(v)&&v>=min&&v<=max)change(()=>s[k]=v);else renderInspector()};bindPointInputs(s,'sv');$('#delete-string').onclick=()=>change(()=>{S.strings=S.strings.filter(x=>x.id!==s.id);selection=null},{controls:true})}
function bindPointInputs(record,prefix){$$('[data-'+prefix+']').forEach(inp=>inp.onchange=()=>{const a=inp.dataset.axis,max=a==='x'?S.width:S.depth,v=+inp.value;if(Number.isFinite(v)&&v>=0&&v<=max)change(()=>record.points[+inp.getAttribute('data-'+prefix)][a]=v/max);else renderInspector()})}
function quickUtility(){if(routeState==='verified'&&!routeReference.trim()){notify('A source or survey reference is required before recording a source-backed existing route.');return}change(()=>{ensureLayer('underground');const r={id:uid(),kind:routeKind,name:UTILITY_TYPES[routeKind].name+' sketch',status:routeState,reference:routeReference.trim(),recorded:new Date().toISOString().slice(0,10),points:[{x:.12,y:Math.min(.86,.28+Object.keys(UTILITY_TYPES).indexOf(routeKind)*.075+S.routes.filter(x=>x.kind===routeKind).length*.02)},{x:.88,y:Math.min(.86,.28+Object.keys(UTILITY_TYPES).indexOf(routeKind)*.075+S.routes.filter(x=>x.kind===routeKind).length*.02)}]};S.routes.push(r);selection={type:'route',id:r.id};tool='select';draft=[]},{controls:true});notify('Editable '+UTILITY_TYPES[routeKind].name.toLowerCase()+' sketch added. Move the endpoints to your intended route; this is not a located utility.')}
function routeInspector(r){return `<h3>${esc(UTILITY_TYPES[r.kind]?.name||'Service route')}</h3><span class="object-badge">${pathLength(r).toFixed(1)} ft · ${esc(ROUTE_STATES[r.status]||'Unverified')}</span><label class="field">Service type<select id="edit-route-kind">${Object.entries(UTILITY_TYPES).map(([k,u])=>`<option value="${k}" ${r.kind===k?'selected':''}>${u.name}</option>`).join('')}</select></label><label class="field">Record status<select id="edit-route-state">${Object.entries(ROUTE_STATES).map(([k,n])=>`<option value="${k}" ${r.status===k?'selected':''}>${n}</option>`).join('')}</select></label><label class="field">Source / ticket / survey<input id="edit-route-reference" type="text" maxlength="160" value="${esc(r.reference||'')}"></label><button class="outline-btn" id="save-route-details">Update service record</button><p class="note">Drag the numbered nodes or enter coordinates. Coloured routes are design records, not engineering instructions. No depth or separation is inferred.</p>${pointFields(r.points,'rv')}<button class="text-btn" id="add-route-point">+ Add waypoint</button><button class="text-btn delete-photo" id="delete-route">Remove this route</button>`}
function bindRouteInspector(r){$('#save-route-details').onclick=()=>{const status=$('#edit-route-state').value,ref=$('#edit-route-reference').value.trim();if(status==='verified'&&!ref){notify('Record a source or survey reference first.');return}change(()=>{r.kind=$('#edit-route-kind').value;r.status=status;r.reference=ref;r.recorded=new Date().toISOString().slice(0,10);r.name=UTILITY_TYPES[r.kind].name+' route'})};bindPointInputs(r,'rv');$('#add-route-point').onclick=()=>{if(r.points.length>=50)return;change(()=>{const a=r.points[0],b=r.points[1];r.points.splice(1,0,{x:(a.x+b.x)/2,y:(a.y+b.y)/2})})};$('#delete-route').onclick=()=>change(()=>{S.routes=S.routes.filter(x=>x.id!==r.id);selection=null},{controls:true})}
function renderLayerCanvas(){const b=bounds(),d=pathFor(vertices(),b,S.shape==='curve'),L=S.layers,underground=S.layers.underground&&!S.layers.ground&&!S.layers.above,night=S.night&&!underground,selected=selection,viewW=850*100/viewZoom,viewH=620*100/viewZoom;$('#garden').setAttribute('viewBox',`${425-viewW/2} ${310-viewH/2} ${viewW} ${viewH}`);$('#garden-stage').classList.toggle('night',night);$('#garden-stage').classList.toggle('underground-mode',underground);$('#garden-stage').style.cursor=tool==='select'?'default':'crosshair';$('#plan-view').classList.toggle('active',!photoMode);$('#photo-view').classList.toggle('active',photoMode);let h=patterns()+`<defs><clipPath id="boundary"><path d="${d}"/></clipPath></defs><rect x="-300" y="-300" width="1450" height="1220" fill="${night?'#243b39':underground?'#eef0e7':'#e8ecdf'}"/><rect x="-300" y="-300" width="1450" height="1220" fill="url(#grid)"/>`;
if(photoMode&&photoData&&!underground)h+=`<image href="${photoData}" width="850" height="620" preserveAspectRatio="xMidYMid meet" opacity=".4"/>`;
h+=`<path d="${d}" fill="${L.ground?MATERIALS[S.material].fill:night?'#36503e':'#e1e8d7'}" stroke="#728569" stroke-width="2" opacity="${photoMode?.28:1}"/><g clip-path="url(#boundary)">`;
if(L.ground){S.zones.forEach(z=>h+=`<path data-zone-id="${esc(z.id)}" d="${pathFor(z.points,b)}" fill="url(#soil)" stroke="${selected?.id===z.id?'#a63e2e':'#84795b'}" stroke-width="${selected?.id===z.id?3:1}"/>`);h+=pathMarkup(b);if(night)h+=`<path d="${d}" fill="#17372e" opacity=".45"/>`}else h+=referenceFootprints(b);
if(L.above&&night&&S.lights)S.items.filter(i=>CATALOG[i.kind].type==='light').forEach(i=>{const p=xy(i,b);h+=`<circle cx="${p.x}" cy="${p.y}" r="${b.scale*4}" fill="url(#halo)"/>`});h+='</g>';
if(L.above)for(const i of S.items){const p=xy(i,b),w=i.w*b.scale,hh=i.h*b.scale,isSelected=selected?.type==='item'&&selected.id===i.id;h+=`<g class="svg-object" data-item-id="${esc(i.id)}" tabindex="0" role="button" aria-label="Select ${esc(CATALOG[i.kind].name)}" transform="translate(${p.x} ${p.y}) rotate(${i.angle})"><title>${esc(CATALOG[i.kind].name)} · ${i.w} × ${i.h} ft</title><rect x="${-w/2}" y="${-hh/2}" width="${w}" height="${hh}" rx="3" fill="#f7f2df" fill-opacity=".08" stroke="${isSelected?'#a63e2e':'#5f7655'}" stroke-width="${isSelected?2.5:.8}" stroke-dasharray="${isSelected?'5 3':'2 4'}"/><ellipse cy="${hh*.2}" rx="${w*.45}" ry="${hh*.24}" fill="#2d482e" opacity=".14"/><g transform="scale(${w/100} ${hh/100})">${icon(i.kind)}</g></g>`}if(L.above)for(const i of S.items)if(S.labels||(selected?.type==='item'&&selected.id===i.id))h+=itemLabel(i,b);if(L.above)for(const s of S.strings)h+=stringMarkup(s);
// Services are always drawn LAST so pools, paving, furniture and labels cannot conceal them.
if(L.underground){h+=`<g id="underground-services">`;for(const r of S.routes)h+=technicalRouteMarkup(r,b);h+='</g>'}
h+=`<path d="${d}" fill="none" stroke="${night?'#adb99a':'#6b8060'}" stroke-width="2" pointer-events="none"/>`;
if(S.step===0)S.points.forEach((p,i)=>{const q=xy(p,b);h+=`<g data-vertex-id="${i}" class="svg-handle"><circle cx="${q.x}" cy="${q.y}" r="10" fill="#f7eed9" stroke="#a63e2e" stroke-width="2"/><text x="${q.x}" y="${q.y+4}" text-anchor="middle" font-family="Arial" font-size="10" fill="#a63e2e">${i+1}</text></g>`});if(selection?.type==='zone'&&L.ground){const z=S.zones.find(x=>x.id===selection.id);z?.points.forEach((p,i)=>{const q=xy(p,b);h+=`<circle data-zone-vertex="${i}" class="svg-handle" cx="${q.x}" cy="${q.y}" r="7" fill="#f2dcaa" stroke="#a63e2e" stroke-width="2"/>`})}
if(draft.length){const color=tool==='route'?(UTILITY_TYPES[routeKind]?.color||'#a63e2e'):tool==='string'?'#c4a45b':'#a63e2e';h+=`<polyline points="${pointsString(draft,b)}" fill="${tool==='soil'?'#aa936655':'none'}" stroke="${color}" stroke-width="4" stroke-dasharray="6 4"/>`;draft.forEach(p=>{const q=xy(p,b);h+=`<circle cx="${q.x}" cy="${q.y}" r="6" fill="#f7edcf" stroke="${color}" stroke-width="2"/>`})}
if(underground&&!S.routes.length)h+=`<g pointer-events="none"><rect x="215" y="245" width="420" height="90" rx="5" fill="#f8f4e8" stroke="#b8c2ac"/><text x="425" y="278" text-anchor="middle" font-size="16" font-family="Georgia" fill="#36543d">No underground routes have been recorded yet.</text><text x="425" y="304" text-anchor="middle" font-size="11" font-family="Arial" fill="#6b7d60">Choose a service, then draw or add an editable sketch.</text></g>`;
h+=`<text x="425" y="${b.y-25}" text-anchor="middle" font-size="11" font-family="Arial" fill="${night?'#d2dcc0':'#5f7557'}">${S.width} ft</text><text x="${b.x-25}" y="${b.y+b.h/2}" text-anchor="middle" font-size="11" font-family="Arial" fill="${night?'#d2dcc0':'#5f7557'}" transform="rotate(-90 ${b.x-25} ${b.y+b.h/2})">${S.depth} ft</text>`;$('#garden').innerHTML=namespaceResources(h,'plan-');renderPlanSelector();$('#area-tag').textContent=Math.round(areaOf(borderSamples()))+' sq ft · '+(VIEW_PRESETS[S.view]?.name||'Custom layers');$('#canvas-note').textContent=tool==='route'?'Tap route points, then Finish route.':tool==='string'?'Tap string-light anchors, then Finish light strand.':tool==='path'?'Tap walkway waypoints, then finish.':tool==='soil'?'Tap soil boundary points, then finish.':photoMode?'PHOTO REFERENCE · manually aligned, not a measured survey.':underground?'UNDERGROUND PLAN · diagram colours are not field utility markings. Drag a selected route’s numbered nodes.':S.view==='above'?'ABOVE-GROUND PLAN · labelled footprints, objects and overhead lights.':'Select any placed element from the dropdown, even if another item covers it.'}
function renderLayerPerspective(){const b=bounds(),d=pathFor(vertices(),b,S.shape==='curve'),L=S.layers,under=S.layers.underground&&!S.layers.ground&&!S.layers.above,night=S.night&&!under,a=.86,bb=-.12,c=.38,dd=.48,e=500-a*425-c*310,f=360-bb*425-dd*310,project=p=>{const q=xy(p,b);return{x:a*q.x+c*q.y+e,y:bb*q.x+dd*q.y+f}},matrix=(dy=0)=>`matrix(${a} ${bb} ${c} ${dd} ${e} ${f+dy})`,offset=135;let h=patterns()+`<defs><clipPath id="p-boundary"><path d="${d}"/></clipPath><linearGradient id="scene-sky" x2="0" y2="1"><stop stop-color="${night?'#253d40':'#e4dfc5'}"/><stop offset="1" stop-color="${night?'#435d50':'#f0ead7'}"/></linearGradient></defs><rect width="1000" height="720" fill="url(#scene-sky)"/><path d="M0 270Q220 160 450 250T1000 220V720H0Z" fill="${night?'#324e41':'#bbc6a4'}" opacity=".6"/>`;
if(L.underground){h+=`<g transform="${matrix(offset)}"><path d="${d}" fill="#e2dfcf" stroke="#8c9e8d" stroke-width="2"/><path d="${d}" fill="url(#grid)"/></g>`;for(const p of vertices()){const q=project(p);h+=`<path d="M${q.x} ${q.y}v${offset}" stroke="#899f8a" stroke-dasharray="4 7" stroke-width="1" opacity=".55"/>`}}
h+=`<g transform="${matrix()}"><path d="${d}" fill="${L.ground?MATERIALS[S.material].fill:night?'#3a5540':'#dbe3cc'}" opacity="${under?.2:1}" stroke="#768d6e" stroke-width="2"/><g clip-path="url(#p-boundary)">`;if(L.ground){S.zones.forEach(z=>h+=`<path d="${pathFor(z.points,b)}" fill="url(#soil)"/>`);h+=pathMarkup(b)}else if(S.references)h+=referenceFootprints(b);if(night)h+=`<path d="${d}" fill="#13382d" opacity=".4"/>`;h+='</g></g>';
if(L.above){for(const i of [...S.items].sort((i,j)=>project(i).y-project(j).y)){const p=project(i),cat=CATALOG[i.kind],scale=clamp(i.w*b.scale/82,.25,3.5);if(cat.occupies)h+=facilityPerspective(i,project,b);else h+=`<g transform="translate(${p.x} ${p.y})"><ellipse cy="4" rx="${scale*26}" ry="${scale*9}" fill="#2b4a31" opacity=".15"/><g transform="scale(${scale})">${icon(i.kind,'side')}</g></g>`;if(S.labels)h+=`<text x="${p.x}" y="${p.y+23}" text-anchor="middle" font-size="10" font-family="Arial" fill="${night?'#ece3bf':'#35513a'}" paint-order="stroke" stroke="${night?'#2c4638':'#eee9d6'}" stroke-width="3">${esc(cat.name.replace(/ concept$/,''))}</text>`;if(night&&S.lights&&cat.type==='light')h+=`<circle cx="${p.x}" cy="${p.y-scale*23}" r="${scale*23}" fill="url(#halo)"/>`}for(const strand of S.strings)h+=stringMarkup(strand,{project})}
if(L.underground){for(const route of S.routes)h+=technicalRouteMarkup(route,b,{project,offset});if(!S.routes.length)h+=`<text x="500" y="550" text-anchor="middle" font-size="14" font-family="Georgia" fill="#59725a">No service routes recorded — add them in Underground view.</text>`;h+=`<text x="500" y="640" text-anchor="middle" font-size="11" font-family="Arial" fill="${night?'#e8e1c5':'#526b54'}">UNDERGROUND SERVICE LAYER · EXPLODED FOR CLARITY · NO BURIAL DEPTH IMPLIED</text>`}
h+=`<text x="500" y="675" text-anchor="middle" font-size="15" font-family="Georgia" font-style="italic" fill="${night?'#e7ddbb':'#5c7355'}">${esc(S.name)} · ${VIEW_PRESETS[S.view]?.name||'Custom layers'} · ${S.season} ${night?'evening':'daylight'}</text>`;$('#perspective').innerHTML=namespaceResources(h,'scene-');$('#render-status').textContent='V'+S.version+' · '+(VIEW_PRESETS[S.view]?.name||'Custom layers')+' · '+S.routes.length+' utility routes · '+S.strings.length+' light strands';const controls=$('#preview-layer');if(controls)controls.value=S.view==='custom'?'composite':S.view}
function extraIcon(kind,mode='top'){const cat=CATALOG[kind],art=cat.art,side=mode==='side',g=cat.foliage||plantColor(),bloom=cat.bloom||'#c8a1aa';if(['pool','roundpool','pond','fountain','wall','stonewall','fence','platform','pergola','steps','counter','bbqisland','sink','oven','lounger','sofa'].includes(art))return expandedIcon(kind,mode);if(['tree','fruit','hydrangea','hedge','rose','daisy','ground','leaf','grass','herbbed','spotlight'].includes(art))return expandedIcon(kind,mode);if(['palm','fern','plume','iris','allium','blossom'].includes(art)){if(art==='blossom')return `<g>${icon('olive',mode)}<g fill="${bloom}" stroke="#b4928b">${[[-20,-20],[0,-31],[20,-18],[-9,-4],[13,-1]].map(([x,y])=>`<circle cx="${x}" cy="${side?y-45:y}" r="7"/>`).join('')}</g></g>`;if(art==='palm')return `<g stroke="#63764d" stroke-width="2" fill="${g}" transform="translate(0 ${side?-48:0})">${[0,60,120,180,240,300].map(r=>`<path d="M0 0Q-24-33 0-45Q23-25 0 0Z" transform="rotate(${r})"/>`).join('')}<path d="M0 4v${side?52:12}" stroke="#8c7752" stroke-width="5"/></g>`;if(art==='fern')return `<g stroke="${g}" stroke-width="2" fill="${g}" transform="translate(0 ${side?-15:0})">${[-50,-25,0,25,50].map(r=>`<g transform="rotate(${r})"><path d="M0 26V-37"/>${[-25,-12,1,14].map(y=>`<path d="M0 ${y}q-23-15-17-20 17 3 17 20m0 0q23-15 17-20-17 3-17 20"/>`).join('')}</g>`).join('')}</g>`;if(art==='plume')return `<g transform="translate(0 ${side?0:25})" stroke="${g}" fill="#d2c293">${[-25,-10,8,24].map((x,j)=>`<path d="M0 20Q${x} 0 ${x} -44" stroke-width="2" fill="none"/><ellipse cx="${x}" cy="${-45-j%2*10}" rx="5" ry="18" transform="rotate(${x/2} ${x} -45)"/>`).join('')}</g>`;return `<g transform="translate(0 ${side?-4:20})" stroke="#698257" fill="${bloom}">${[-20,0,20].map((x,j)=>`<path d="M${x/2} 24L${x} ${-34-j%2*10}" stroke-width="2"/><circle cx="${x}" cy="${-38-j%2*10}" r="${art==='allium'?12:8}"/><ellipse cx="${x}" cy="${-38-j%2*10}" rx="4" ry="16" transform="rotate(50 ${x} -38)"/>`).join('')}</g>`}
if(art==='dining')return `<g fill="#d9c6a0" stroke="#52664c" stroke-width="2"><rect x="-40" y="-27" width="80" height="54" rx="5"/>${[-28,0,28].map(x=>`<rect x="${x-10}" y="-43" width="20" height="12" rx="4"/><rect x="${x-10}" y="31" width="20" height="12" rx="4"/>`).join('')}</g>`;if(art==='chair')return `<g stroke="#4b6245" stroke-width="2" fill="#cec9a5"><rect x="-29" y="-35" width="58" height="70" rx="10"/><rect x="-25" y="-30" width="50" height="22" rx="7" fill="#9ba783"/><path d="M-34-12v39m68-39v39" stroke-width="5"/></g>`;
if(['firebowl','birdbath'].includes(art))return `<g stroke="#7c765d" stroke-width="3"><ellipse cy="${side?-20:0}" rx="40" ry="${side?17:40}" fill="#c3b894"/><ellipse cy="${side?-22:0}" rx="31" ry="${side?10:31}" fill="${art==='birdbath'?'#9ab7ae':'#7a7052'}"/>${side?'<path d="M-6-5V15H6V-5" fill="#b4ac88"/>':''}${art==='firebowl'?'<path d="M-8 10q-18-17 3-35-4 18 9 9 13 17-3 27Z" fill="#d6a35f" stroke="#b67a45"/>':''}</g>`;
if(art==='planter')return `<g>${icon('vegbed',mode)}</g>`;
if(['gate','trellis','bridge','cabinet'].includes(art))return `<g fill="${art==='cabinet'?'#9b9e81':'#b89b70'}" stroke="#6e795d" stroke-width="2"><rect x="-42" y="${side?-55:-38}" width="84" height="${side?60:76}" rx="3"/><path d="M-28-38v76m14-76v76M0-38v76m14-76v76m14-76v76M-42-20h84m-84 40h84" fill="none"/><path d="M-40 32L40-32" fill="none"/></g>`;
if(art==='lantern')return icon('lantern',mode);if(['walllight','bollard','pendant','decklight'].includes(art))return `<g transform="translate(0 ${side?-16:0})" stroke="#4c6146" stroke-width="2"><rect x="-20" y="-26" width="40" height="50" rx="${art==='pendant'?15:4}" fill="#e8d8a2"/><path d="M-13-21h26m-26 36h26M-12-26v50m24-50v50"/><path d="M0-26v-16m-12 70h24" stroke-width="3"/></g>`;return icon('pot',mode)}
function focusForStep(n){const key=GARDEN_PHASES[n]?.view||'composite',p=VIEW_PRESETS[key];S.view=key;S.layers={ground:p.ground,above:p.above,underground:p.underground};viewZoom=100}
function assetSet(step){const groups=step===5?PLANT_GROUPS:step===6?BUILD_GROUPS:null;return {groups,available:Object.entries(CATALOG).filter(([k,c])=>step===5?c.type==='plant':step===6?c.type!=='plant'&&c.type!=='light':c.type==='light')}}
function assetCards(step){const {groups,available}=assetSet(step),needle=catalogSearch.trim().toLowerCase(),matches=available.filter(([k,c])=>(!groups||catalogGroup==='all'||c.group===catalogGroup)&&(!needle||(c.name+' '+(groups?.[c.group]||'')).toLowerCase().includes(needle)));return matches.length?matches.map(([k,c])=>`<button data-add="${k}" title="${esc(c.info)}">${catalogThumb(k)}<span>${c.name}</span><small>${c.price===null?'Quote required':money(c.price)+' · demo'}</small></button>`).join(''):'<p class="note">No matching design symbols. Try a shorter name or another category.</p>'}
function improvedCatalogPicker(step){const {groups,available}=assetSet(step);if(groups&&catalogGroup!=='all'&&!groups[catalogGroup])catalogGroup='all';return `<div class="asset-library-heading"><span class="eyebrow">${available.length} ${step===5?'planting':step===6?'garden':'lighting'} options</span><label class="field">Search this library<input id="catalog-search" type="search" placeholder="${step===5?'Try grass, fern, flower…':'Try pergola, counter, light…'}" value="${esc(catalogSearch)}"></label>${groups?`<label class="field">Browse ${step===5?'planting':'garden elements'}<select id="catalog-group"><option value="all">All options (${available.length})</option>${Object.entries(groups).map(([k,n])=>`<option value="${k}" ${catalogGroup===k?'selected':''}>${n} (${available.filter(([,c])=>c.group===k).length})</option>`).join('')}</select></label>`:''}</div><div id="asset-results" class="catalog expanded-catalog">${assetCards(step)}</div><p class="note">Design symbols and demo supply allowances. Product stock, plant suitability and final product dimensions must be checked.</p>`}
function bindAssetCards(){const bind=()=>$$('[data-add]').forEach(b=>b.onclick=()=>{const k=b.dataset.add;if(S.items.length>=150){notify('This plan supports up to 150 objects.');return}change(()=>{ensureLayer('above');const obj={id:uid(),kind:k,x:.5+(S.items.length%3-1)*.08,y:.5,w:CATALOG[k].w,h:CATALOG[k].h,angle:0};if(CATALOG[k].height)obj.height=CATALOG[k].height;S.items.push(obj);selection={type:'item',id:obj.id};tool='select'});notify(CATALOG[k].name+' added to the above-ground layer.')});bind();if($('#catalog-search'))$('#catalog-search').oninput=e=>{catalogSearch=e.target.value;$('#asset-results').innerHTML=assetCards(S.step);bind()}}

function namespaceResources(markup,prefix){const ids=[...markup.matchAll(/<(?:pattern|clipPath|linearGradient|radialGradient|filter|mask)\s+id="([^"]+)"/g)].map(m=>m[1]);for(const id of ids)markup=markup.replaceAll(`id="${id}"`,`id="${prefix}${id}"`).replaceAll(`url(#${id})`,`url(#${prefix}${id})`);return markup}
function thumbnailArt(k){const art=icon(k),refs=[...art.matchAll(/url\(#([^)]*)\)/g)].map(m=>m[1]),keys=Object.keys(MATERIALS).filter(key=>refs.includes(textureId(key)));return namespaceResources(`<defs>${keys.map(key=>materialTexture(key)).join('')}</defs>${art}`,'thumb-'+k+'-')}

function drawingLabelScale(perspective=false){if(typeof document==='undefined')return 1;const el=document.querySelector(perspective?'#render-frame':'#garden-stage'),width=el?.getBoundingClientRect().width||850;return Math.max(1,Math.min(2.6,(perspective?1000:850)/width))}
